#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct BrandDesignTokens {
    pub typography: TypographyTokens,
    pub spacing: SpacingTokens,
    pub radii: RadiiTokens,
    pub motion: MotionTokens,
    pub glass: GlassStructureTokens,
    /// Ordered theme registry. Add one entry here and every platform picks it up
    /// through `pnpm tokens:sync` — consumers look palettes up by key, never branch.
    pub themes: Vec<ThemeModeTokens>,
}

/// Registry key of the theme applied before the user (or OS) has chosen one.
pub const DEFAULT_THEME: &str = "dark";

impl BrandDesignTokens {
    /// Palette for a registry key. The panic is unreachable for keys shipped in
    /// [`default_design_tokens`]; tests cover every key.
    #[allow(
        clippy::expect_used,
        reason = "the registry is a compile-time table; tests resolve every shipped key"
    )]
    pub fn theme(&self, mode: &str) -> &ThemeModeTokens {
        self.themes
            .iter()
            .find(|theme| theme.mode == mode)
            .expect("theme must exist in the registry")
    }
}

