/// Registry in canonical order — also the order pickers render on web and native.
fn all_themes() -> Vec<ThemeModeTokens> {
    vec![
        light_theme_tokens(),
        dark_theme_tokens(),
        black_theme_tokens(),
        sepia_theme_tokens(),
    ]
}

